import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import Counter from './Counter';

test('increments on click', async () => {
  render(<Counter />);
  // QUERY BY ROLE/LABEL (the way a user finds it), not by test id or class.
  const btn = screen.getByRole('button', { name: /0/i });
  await userEvent.click(btn);
  // ASSERT what the user SEES (behavior), not internal state.
  expect(screen.getByRole('button', { name: /1/i })).toBeInTheDocument();
});

// The principle: TEST BEHAVIOR, NOT IMPLEMENTATION.
//   BAD:  expect(Counter.state.count).toBe(1);          // internal state
//   BAD:  expect(useState).toHaveBeenCalledTimes(1);      // hook internals
//   GOOD: expect(button).toHaveTextContent('1');         // what the user sees
//
//   A refactor (class -> hooks, hooks -> signals) BREAKS implementation
//   tests but NOT behavior tests -> behavior tests are robust.
